// SPDX-License-Identifier: MIT
// Spike S5 (Requirements 20.13, 19.2). Disposable prototype of the Renderizador próprio for the `feature` demand: layout with
// @dagrejs/dagre in a Web Worker, SVG generated by the kit (tests/browser/spike/s5/*, outside the build). Measures, in the harness
// of tests/browser/spike/s1-s2.spec.ts and s3-s4.spec.ts (real Modelo_de_Grafo from gerarGrafo, CPU 4x, fresh browser context per
// run, p95 over the runs):
//   1. total time (conversion + layout in the worker + SVG generation + DOM insertion) for Visão geral, 5 raias, completo and
//      completo with Subtarefas, against the Mermaid p95 recorded by S1 (docs/spike-fluxos/s1-s2.json);
//   2. mouse response while the prototype renders (target < 100 ms), worker against the layout on the main thread (control);
//   3. kB gzip (level 9) of the prototype + dagre;
//   4. visual difference against the Mermaid render of the same set: counts of nodes, edges and clusters, label-overlap,
//      text overflow, and a coarse pixel comparison of screenshots. The `completo` text is checked against the golden file.
// No limit is asserted: the numbers go to docs/spike-fluxos/s5.json.
//
// Requires a built site (vendored Mermaid in site/dist/vendor/mermaid): KIT_LOCALES=pt-BR npm run build
// dagre is NOT a dependency of the kit. Install it outside the repo and point SPIKE_DAGRE_DIR to it:
//   mkdir -p /tmp/spike-dagre && cd /tmp/spike-dagre && npm init -y && npm i @dagrejs/dagre
// Optional: SPIKE_RUNS=<n> (default 10), SPIKE_ONLY=desempenho|mouse|visual.
import { expect, test } from '@playwright/test';
import type { Browser, Page } from '@playwright/test';
import { build } from 'esbuild';
