// ------------------------------------------------------------------ 1. desempenho
interface Medida {
  entrada_ms: number;
  layout_ms: number;
  layout_no_worker_ms: number | null;
  svg_ms: number;
  insercao_ms: number;
  total_ms: number;
  ate_quadro_ms: number;
  svg_chars: number;
  nos: number;
  clusters: number;
  arestas: number;
}
interface RodadaDesempenho {
  worker_boot_ms: number;
  primeira_visao_geral: Medida;
  worker: Record<string, Medida>;
  principal?: Record<string, Medida>;
}

async function rodarDesempenho(browser: Browser, controle: boolean): Promise<RodadaDesempenho> {
  const { page, fechar: fecharCtx } = await abrir(browser);
  try {
    return await page.evaluate(
      async ({ worker, glue, g, conjuntos, aq, controle }) => {
        const s5 = (window as any).__s5;
        const alvo = document.getElementById('alvo') as HTMLElement;
        const mk = (c: any) => ({ raias: new Set<string>(c.raias), subtarefas: new Set<string>(), todasSubtarefas: c.todasSubtarefas });
        const w = s5.layoutNoWorker(worker);
        const boot = (await w.pronto) as number;
        const primeira = await s5.renderizar(g, mk(conjuntos[0]), w.layouter, alvo);
        alvo.innerHTML = '';
        await s5.renderizar(g, mk(aq), w.layouter, alvo);
        const saida: any = { worker_boot_ms: boot, primeira_visao_geral: primeira, worker: {} };
        for (const c of conjuntos) {
          saida.worker[c.id] = await s5.renderizar(g, mk(c), w.layouter, alvo);
          alvo.innerHTML = '';
        }
        w.encerrar();
        if (controle) {
          const s = document.createElement('script');
          s.textContent = glue;
          document.head.appendChild(s);
          // Dagre needs the same warm-up on the main thread, otherwise the first set would pay JIT cost the worker did not.
          await s5.renderizar(g, mk(aq), s5.layoutNaThreadPrincipal, alvo);
          saida.principal = {};
          for (const c of conjuntos) {
            saida.principal[c.id] = await s5.renderizar(g, mk(c), s5.layoutNaThreadPrincipal, alvo);
            alvo.innerHTML = '';
          }
        }
        return saida;
      },
      { worker: codigoWorker, glue: codigoWorker, g: grafoJson, conjuntos: CONJUNTOS, aq: aquecimento, controle },
    );
  } finally {
    await fecharCtx();
  }
}

const CAMPOS: Array<keyof Medida> = ['total_ms', 'ate_quadro_ms', 'entrada_ms', 'layout_ms', 'layout_no_worker_ms', 'svg_ms', 'insercao_ms'];
function agregar(rodadas: Array<Record<string, Medida>>, id: string, estimar4xNoWorker = false) {
  const ms = rodadas.map((r) => r[id]).filter(Boolean);
  const out: Record<string, unknown> = { execucoes_ok: ms.length };
  for (const c of CAMPOS) {
    const xs = ms.map((m) => m[c]).filter((x): x is number => typeof x === 'number');
    out[c] = xs.length ? resumo(xs) : null;
  }
  if (estimar4xNoWorker) {
    // The Worker is not slowed by the CPU 4x (see `calibragem_do_cpu_4x`): add the missing (4 - 1) x layout time.
    const est = ms.filter((m) => typeof m.layout_no_worker_ms === 'number').map((m) => m.total_ms + (CPU_RATE - 1) * (m.layout_no_worker_ms as number));
    out.total_estimado_se_o_worker_fosse_4x_ms = est.length ? resumo(est) : null;
  }
  const um = ms[0];
  out.tamanho = um ? { nos_no_layout: um.nos, clusters: um.clusters, arestas: um.arestas, svg_chars: um.svg_chars } : null;
  return out;
}

test('S5: tempo total (layout no Worker, SVG e DOM) com CPU 4x', async ({ browser }) => {
  test.skip(!!ONLY && ONLY !== 'desempenho', 'SPIKE_ONLY');
  test.setTimeout(0);
  const rodadas: RodadaDesempenho[] = [];
  const erros: string[] = [];
  for (let i = 0; i < RUNS; i++) {
    try {
      rodadas.push(await rodarDesempenho(browser, i < RUNS_CONTROLE));
    } catch (e) {
      erros.push(String((e as Error).message).slice(0, 300));
    }
  }
  const ref = referenciaMermaid();
  const porConjunto: Record<string, unknown> = {};
  for (const c of CONJUNTOS) {
    const w = agregar(rodadas.map((r) => r.worker), c.id, true) as any;
    const p = agregar(rodadas.filter((r) => r.principal).map((r) => r.principal as Record<string, Medida>), c.id) as any;
    const protoP95 = w.total_ms?.p95 ?? null;
    porConjunto[c.id] = {
      worker: w,
      controle_layout_na_thread_principal_cpu_4x: p,
      mermaid_s1_p95_ms: ref[c.id],
      ganho_sobre_mermaid_x: protoP95 && ref[c.id] ? round(ref[c.id]! / protoP95, 1) : null,
      ganho_sobre_mermaid_controle_x: p.total_ms?.p95 && ref[c.id] ? round(ref[c.id]! / p.total_ms.p95, 1) : null,
      ganho_sobre_mermaid_worker_estimado_4x_x: w.total_estimado_se_o_worker_fosse_4x_ms?.p95 && ref[c.id] ? round(ref[c.id]! / w.total_estimado_se_o_worker_fosse_4x_ms.p95, 1) : null,
    };
  }
  relatorio.desempenho = {
    execucoes_ok: rodadas.length,
    erros,
    worker_boot_ms: resumo(rodadas.map((r) => r.worker_boot_ms)),
    primeira_visao_geral: {
      descricao: 'primeira renderização depois do boot do Worker, sem aquecimento (JIT do dagre e do gerador a frio)',
      total_ms: resumo(rodadas.map((r) => r.primeira_visao_geral.total_ms)),
      layout_no_worker_ms: resumo(rodadas.map((r) => r.primeira_visao_geral.layout_no_worker_ms ?? 0)),
    },
    por_conjunto: porConjunto,
    referencia_mermaid: `p95 de docs/spike-fluxos/s1-s2.json (${S1}), mesmo harness, CPU 4x, 10 execuções; o Mermaid completo roda na thread principal`,
  };
  fechar(browser.version());
  expect(rodadas.length).toBeGreaterThan(0);
});

test('S5: o CPU 4x vale para o Worker?', async ({ browser }) => {
  test.skip(!!ONLY && ONLY !== 'desempenho', 'SPIKE_ONLY');
  test.setTimeout(0);
  const medir = async (throttle: boolean) => {
    const { page, fechar: fecharCtx } = await abrir(browser, { throttle });
    try {
      return await page.evaluate(async () => {
        const laco = 'let x = 0; for (let i = 0; i < 6e7; i++) x += i % 7; return x;';
        const t0 = performance.now();
        new Function(laco)();
        const principal = performance.now() - t0;
        const url = URL.createObjectURL(new Blob([`onmessage = () => { const t = performance.now(); (function(){ ${laco} })(); postMessage(performance.now() - t); };`], { type: 'text/javascript' }));
        const w = new Worker(url);
        const noWorker = await new Promise<number>((res) => {
          w.onmessage = (ev) => res(ev.data);
          w.postMessage(0);
        });
        w.terminate();
        return { principal, worker: noWorker };
      });
    } finally {
      await fecharCtx();
    }
  };
  const sem = await medir(false);
  const com = await medir(true);
  relatorio.calibragem_do_cpu_4x = {
    laco_fixo_ms: { sem_throttling: { principal: r1(sem.principal), worker: r1(sem.worker) }, cpu_4x: { principal: r1(com.principal), worker: r1(com.worker) } },
    razao_principal: round(com.principal / sem.principal, 2),
    razao_worker: round(com.worker / sem.worker, 2),
    worker_sofre_o_throttling: com.worker / sem.worker > 2,
    leitura: 'razão perto de 4 = o Worker também é desacelerado; perto de 1 = só a thread principal é. Neste caso o `layout_no_worker_ms` do caso Worker subestima um aparelho 4x mais lento, e o controle (layout na thread principal sob 4x) é o teto conservador.',
  };
  fechar(browser.version());
});

// ------------------------------------------------------------------ 2. resposta do mouse
async function instrumentar(page: Page) {
  await page.evaluate(() => {
    const w = window as any;
    w.__mov = [] as number[];
    w.__lt = [] as number[];
    w.__raf = [] as number[];
    addEventListener('mousemove', (e) => w.__mov.push(performance.now() - e.timeStamp), true);
    try {
      new PerformanceObserver((l) => {
        for (const e of l.getEntries()) w.__lt.push(e.duration);
      }).observe({ entryTypes: ['longtask'] });
    } catch {
      /* longtask unsupported */
    }
    let ultimo = performance.now();
    const tick = () => {
      const n = performance.now();
      w.__raf.push(n - ultimo);
      ultimo = n;
      if (!w.__parar) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });
}

async function rodarMouse(browser: Browser, modo: 'worker' | 'principal', id: string, repeticoes: number) {
  const { page, fechar: fecharCtx } = await abrir(browser);
  try {
    let terminou = false;
    await page.exposeFunction('__fim', () => {
      terminou = true;
    });
    // Worker (or glue) ready and warm before the mouse starts.
    await page.evaluate(
      async ({ worker, g, aq, modo }) => {
        const s5 = (window as any).__s5;
        const w = (window as any);
        const alvo = document.getElementById('alvo') as HTMLElement;
        const mk = (c: any) => ({ raias: new Set<string>(c.raias), subtarefas: new Set<string>(), todasSubtarefas: c.todasSubtarefas });
        if (modo === 'worker') {
          w.__w = s5.layoutNoWorker(worker);
          await w.__w.pronto;
          w.__layouter = w.__w.layouter;
        } else {
          const s = document.createElement('script');
          s.textContent = worker;
          document.head.appendChild(s);
          w.__layouter = s5.layoutNaThreadPrincipal;
        }
        await s5.renderizar(g, mk(aq), w.__layouter, alvo);
        alvo.innerHTML = '';
      },
      { worker: codigoWorker, g: grafoJson, aq: aquecimento, modo },
    );
    await instrumentar(page);
    await page.waitForTimeout(300);
    const conj = CONJUNTOS.find((c) => c.id === id)!;
    await page.evaluate(
      ({ g, c, n }) => {
        const w = window as any;
        const alvo = document.getElementById('alvo') as HTMLElement;
        const mk = (x: any) => ({ raias: new Set<string>(x.raias), subtarefas: new Set<string>(), todasSubtarefas: x.todasSubtarefas });
        void (async () => {
          const tempos: number[] = [];
          for (let i = 0; i < n; i++) {
            const m = await w.__s5.renderizar(g, mk(c), w.__layouter, alvo);
            tempos.push(m.total_ms);
            alvo.innerHTML = '';
          }
          w.__tempos = tempos;
          await w.__fim();
        })();
      },
      { g: grafoJson, c: conj, n: repeticoes },
    );
    const roundtrips: number[] = [];
    const ini = performance.now();
    let i = 0;
    while (!terminou && performance.now() - ini < 600_000) {
      const t = performance.now();
      await page.mouse.move(100 + (i % 50) * 10, 150 + (i % 9) * 30);
      roundtrips.push(performance.now() - t);
      i++;
      await sleep(20);
    }
    const d = await page.evaluate(() => {
      const w = window as any;
      w.__parar = true;
      return { mov: w.__mov as number[], lt: w.__lt as number[], raf: w.__raf as number[], tempos: w.__tempos as number[] };
    });
    return {
      moves: roundtrips.length,
      evento_handler_max_ms: maximo(d.mov),
      roundtrip_max_ms: maximo(roundtrips),
      long_task_max_ms: maximo(d.lt),
      long_tasks: d.lt.length,
      raf_gap_max_ms: maximo(d.raf),
      resposta_pior_momento_ms: Math.max(maximo(d.mov) ?? 0, maximo(roundtrips) ?? 0),
      render_total_ms: d.tempos,
    };
  } finally {
    await fecharCtx();
  }
}

test('S5: resposta do mouse durante o render (Worker contra layout na thread principal)', async ({ browser }) => {
  test.skip(!!ONLY && ONLY !== 'mouse', 'SPIKE_ONLY');
  test.setTimeout(0);
  const casos: Array<{ chave: string; modo: 'worker' | 'principal'; id: string; reps: number; runs: number }> = [
    { chave: 'worker_completo', modo: 'worker', id: 'completo', reps: 6, runs: RUNS },
    { chave: 'worker_completo_subtarefas', modo: 'worker', id: 'completo_subtarefas', reps: 4, runs: RUNS },
    { chave: 'controle_thread_principal_completo', modo: 'principal', id: 'completo', reps: 6, runs: RUNS_CONTROLE },
    { chave: 'controle_thread_principal_completo_subtarefas', modo: 'principal', id: 'completo_subtarefas', reps: 4, runs: RUNS_CONTROLE },
  ];
  const out: Record<string, unknown> = {};
  for (const caso of casos) {
    const execs: Array<Awaited<ReturnType<typeof rodarMouse>>> = [];
    const erros: string[] = [];
    for (let i = 0; i < caso.runs; i++) {
      try {
        execs.push(await rodarMouse(browser, caso.modo, caso.id, caso.reps));
      } catch (e) {
        erros.push(String((e as Error).message).slice(0, 200));
      }
    }
    const pick = (f: (e: (typeof execs)[number]) => number | null) => execs.map(f).filter((x): x is number => x !== null);
    const resposta = pick((e) => e.resposta_pior_momento_ms);
    out[caso.chave] = {
      modo: caso.modo,
      conjunto: caso.id,
      renderizacoes_seguidas_por_execucao: caso.reps,
      execucoes_ok: execs.length,
      erros,
      moves_por_execucao_mediana: mediana(execs.map((e) => e.moves)),
      evento_handler_max_ms: { p95_das_execucoes: r1(execs.length ? p95(pick((e) => e.evento_handler_max_ms)) : null), pior: r1(maximo(pick((e) => e.evento_handler_max_ms))) },
      roundtrip_mouse_max_ms: { p95_das_execucoes: r1(execs.length ? p95(pick((e) => e.roundtrip_max_ms)) : null), pior: r1(maximo(pick((e) => e.roundtrip_max_ms))) },
      long_task_max_ms: { p95_das_execucoes: r1(execs.length ? p95(pick((e) => e.long_task_max_ms)) : null), pior: r1(maximo(pick((e) => e.long_task_max_ms))) },
      raf_gap_max_ms: { p95_das_execucoes: r1(execs.length ? p95(pick((e) => e.raf_gap_max_ms)) : null), pior: r1(maximo(pick((e) => e.raf_gap_max_ms))) },
      resposta_do_mouse_pior_momento_ms: { p95_das_execucoes: r1(resposta.length ? p95(resposta) : null), pior: r1(maximo(resposta)) },
      atende_alvo_menor_que_100ms: resposta.length ? p95(resposta) < ALVO_MS : null,
      render_total_ms_mediana: r1(mediana(execs.flatMap((e) => e.render_total_ms ?? []))),
    };
  }
  relatorio.resposta_do_mouse = {
    alvo: `resposta do mouse abaixo de ${ALVO_MS} ms durante o render (layout no Worker; o SVG e o innerHTML seguem na thread principal)`,
    como_medir:
      'mesma instrumentação de s3-s4.spec.ts: atraso entre event.timeStamp e o handler de mousemove, ida e volta de page.mouse.move (um movimento a cada ~20 ms), long tasks e maior intervalo de rAF; o p95 entre execuções do pior momento de cada execução é comparado ao alvo. Cada execução renderiza o conjunto N vezes em sequência para dar janela de medição',
    casos: out,
  };
  fechar(browser.version());
});

// ------------------------------------------------------------------ 3. diferença visual contra o Mermaid
const CONFIG = { startOnLoad: false, securityLevel: 'strict', theme: 'default', maxTextSize: MERMAID_MAX_TEXT_SIZE, maxEdges: MERMAID_MAX_EDGES, flowchart: { useMaxWidth: false } };

test('S5: diferença visual contra o Mermaid (contagens, label-overlap, pixels)', async ({ browser }) => {
  test.skip(!!ONLY && ONLY !== 'visual', 'SPIKE_ONLY');
  test.setTimeout(0);
  const todas = CONJUNTOS.find((c) => c.id === 'completo')!;
  const textoGolden = readFileSync(GOLDEN, 'utf8');
  const textoCompleto = gerarDiagramaExpandido(grafo, conjDe(todas)).texto;
  const comparacao = { golden: GOLDEN, texto_gerado_igual_ao_golden: textoCompleto === textoGolden, caracteres_do_golden: textoGolden.length };

  // CPU 1x: the visual comparison does not depend on timing, and the Mermaid render of `completo` with Subtarefas is long.
  const { page, fechar: fecharCtx } = await abrir(browser, { mermaid: true, throttle: false, viewport: { width: 1600, height: 1200 } });
  const porConjunto: Record<string, unknown> = {};
  try {
    await page.evaluate(
      async ({ worker, config }) => {
        const w = window as any;
        w.mermaid.initialize(config);
        w.__w = w.__s5.layoutNoWorker(worker);
        await w.__w.pronto;
      },
      { worker: codigoWorker, config: CONFIG },
    );

    /** Counts and geometry checks, run on whichever SVG sits in #cena. */
    const medirCena = (alvo: 'mermaid' | 'proprio') =>
      page.evaluate((alvo) => {
        const cena = document.getElementById('cena') as HTMLElement;
        const svg = cena.querySelector('svg') as SVGSVGElement;
        const rect = (e: Element) => e.getBoundingClientRect();
        const area = (a: DOMRect, b: DOMRect) => {
          const w = Math.min(a.right, b.right) - Math.max(a.left, b.left);
          const h = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
          return w > 1 && h > 1 ? w * h : 0;
        };
        const nos = Array.from(svg.querySelectorAll('g.node'));
        const clusters = Array.from(svg.querySelectorAll('g.cluster'));
        const arestas = svg.querySelectorAll(alvo === 'mermaid' ? 'path.flowchart-link' : 'path.edge');
        const rotulos = alvo === 'mermaid' ? Array.from(svg.querySelectorAll('g.edgeLabel')).filter((e) => (e.textContent ?? '').trim() !== '') : Array.from(svg.querySelectorAll('text.edge-label'));
        const sobreposicoes: string[] = [];
        let clustersMedidos = 0;
        for (const c of clusters) {
          const label = c.querySelector('.cluster-label') ?? c.querySelector('foreignObject') ?? c.querySelector('text');
          if (!label) continue;
          clustersMedidos++;
          const lr = rect(label);
          for (const n of nos) if (area(lr, rect(n)) > 0) sobreposicoes.push(`${(label.textContent ?? '').trim().slice(0, 30)} x ${n.id || n.getAttribute('data-id')}`);
        }
        const vb = svg.viewBox.baseVal;
        const out: any = {
          nos: nos.length,
          clusters: clusters.length,
          arestas: arestas.length,
          rotulos_de_aresta: rotulos.length,
          elementos_no_svg: svg.querySelectorAll('*').length,
          svg_chars: svg.outerHTML.length,
          tamanho_natural: { largura: Math.round(vb.width), altura: Math.round(vb.height), proporcao: Math.round((vb.width / vb.height) * 100) / 100 },
          label_overlap: { clusters_medidos: clustersMedidos, sobreposicoes: sobreposicoes.length, exemplos: sobreposicoes.slice(0, 5) },
        };
        if (alvo === 'proprio') {
          // Cluster box covering a node that does not belong to it, and text that does not fit its shape.
          const paiDe = new Map<string, string>(clusters.map((c) => [c.getAttribute('data-id') ?? '', c.getAttribute('data-pai') ?? '']));
          const ancestrais = (id: string) => {
            const s = new Set<string>();
            for (let p = id; p; p = paiDe.get(p) ?? '') s.add(p);
            return s;
          };
          let clusterCobreNo = 0;
          const exemplos: string[] = [];
          for (const c of clusters) {
            const cr = rect(c.querySelector('rect') as Element);
            for (const n of nos) {
              if (ancestrais(n.getAttribute('data-pai') ?? '').has(c.getAttribute('data-id') ?? '')) continue;
              if (area(cr, rect(n)) > 0) {
                clusterCobreNo++;
                if (exemplos.length < 5) exemplos.push(`${c.getAttribute('data-id')} x ${n.getAttribute('data-id')}`);
              }
            }
          }
          let clusterSobreCluster = 0;
          for (let i = 0; i < clusters.length; i++) {
            for (let j = i + 1; j < clusters.length; j++) {
              const a = clusters[i].getAttribute('data-id') ?? '';
              const b = clusters[j].getAttribute('data-id') ?? '';
              if (ancestrais(a).has(b) || ancestrais(b).has(a)) continue;
              if (area(rect(clusters[i].querySelector('rect') as Element), rect(clusters[j].querySelector('rect') as Element)) > 0) clusterSobreCluster++;
            }
          }
          let excede = 0;
          const excedeEx: string[] = [];
          for (const n of nos) {
            const forma = n.firstElementChild as SVGGraphicsElement;
            const texto = n.querySelector('text') as SVGGraphicsElement;
            const f = forma.getBBox();
            const t = texto.getBBox();
            const losango = forma.tagName.toLowerCase() === 'polygon' && n.querySelector('polygon')?.getAttribute('points')?.split(' ').length === 4;
            const cabe = losango ? t.width / f.width + t.height / f.height <= 1 : t.width <= f.width - 2 && t.height <= f.height;
            if (!cabe) {
              excede++;
              if (excedeEx.length < 5) excedeEx.push(`${n.getAttribute('data-id')}: texto ${Math.round(t.width)}x${Math.round(t.height)} em ${Math.round(f.width)}x${Math.round(f.height)}`);
            }
          }
          out.cluster_cobre_no_alheio = { quantidade: clusterCobreNo, exemplos };
          out.cluster_sobre_cluster_nao_aninhado = clusterSobreCluster;
          out.texto_excede_a_forma = { quantidade: excede, de: nos.length, exemplos: excedeEx };
        }
        return out;
      }, alvo);

    /** Screenshot of #cena with the SVG fitted (preserveAspectRatio meet) in 1600x1200. */
    const foto = async (ajuste: 'meet' | 'none' = 'meet'): Promise<Buffer> => {
      await page.evaluate((ajuste) => {
        const cena = document.getElementById('cena') as HTMLElement;
        cena.style.cssText = 'width:1600px;height:1200px;background:#fff;overflow:hidden;position:relative';
        const svg = cena.querySelector('svg') as SVGSVGElement;
        svg.setAttribute('width', '1600');
        svg.setAttribute('height', '1200');
        svg.style.maxWidth = 'none';
        svg.setAttribute('preserveAspectRatio', ajuste === 'meet' ? 'xMidYMid meet' : 'none');
      }, ajuste);
      return await page.locator('#cena').screenshot();
    };

    const mermaidRender = (texto: string) =>
      page.evaluate(
        async ({ texto }) => {
          const w = window as any;
          const t0 = performance.now();
          const r = await w.mermaid.render('v' + Math.random().toString(36).slice(2), texto);
          (document.getElementById('cena') as HTMLElement).innerHTML = r.svg;
          return performance.now() - t0;
        },
        { texto },
      );
    const proprioRender = (c: Conjunto) =>
      page.evaluate(
        async ({ g, c }) => {
          const w = window as any;
          const mk = (x: any) => ({ raias: new Set<string>(x.raias), subtarefas: new Set<string>(), todasSubtarefas: x.todasSubtarefas });
          const m = await w.__s5.renderizar(g, mk(c), w.__w.layouter, document.getElementById('cena'));
          return m.total_ms as number;
        },
        { g: grafoJson, c },
      );

    /** Coarse comparison: both pictures to a 160x120 grid; mean luminance per cell and ink presence per cell. */
    const compararFotos = (a: Buffer, b: Buffer) =>
      page.evaluate(
        async ({ a, b }) => {
          const grade = async (b64: string) => {
            const blob = await (await fetch('data:image/png;base64,' + b64)).blob();
            const img = await createImageBitmap(blob);
            const c = new OffscreenCanvas(160, 120);
            const x = c.getContext('2d') as OffscreenCanvasRenderingContext2D;
            x.fillStyle = '#fff';
            x.fillRect(0, 0, 160, 120);
            x.drawImage(img, 0, 0, 160, 120);
            const d = x.getImageData(0, 0, 160, 120).data;
            const lum: number[] = [];
            for (let i = 0; i < d.length; i += 4) lum.push((0.2126 * d[i] + 0.7152 * d[i + 1] + 0.0722 * d[i + 2]) / 255);
            return lum;
          };
          const [la, lb] = [await grade(a), await grade(b)];
          let soma = 0;
          let uniao = 0;
          let inter = 0;
          let difTinta = 0;
          for (let i = 0; i < la.length; i++) {
            soma += Math.abs(la[i] - lb[i]);
            const ta = la[i] < 0.98;
            const tb = lb[i] < 0.98;
            if (ta || tb) uniao++;
            if (ta && tb) inter++;
            if (ta !== tb) difTinta++;
          }
          return {
            grade: '160x120',
            diferenca_media_de_luminancia_pct: Math.round((soma / la.length) * 1000) / 10,
            tinta_mermaid_pct: Math.round((la.filter((v) => v < 0.98).length / la.length) * 1000) / 10,
            tinta_proprio_pct: Math.round((lb.filter((v) => v < 0.98).length / lb.length) * 1000) / 10,
            celulas_com_tinta_em_so_um_pct: Math.round((difTinta / la.length) * 1000) / 10,
            iou_da_tinta: uniao ? Math.round((inter / uniao) * 1000) / 1000 : null,
          };
        },
        { a: a.toString('base64'), b: b.toString('base64') },
      );

    const fotoNoMermaid = async (_c: Conjunto, texto: string): Promise<Buffer> => {
      // Mermaid is on screen no more (the prototype replaced it): the stretched photo of the prototype is taken first, so re-render Mermaid, shoot, and let the caller re-render.
      await mermaidRender(texto);
      return foto('none');
    };
    const dir = join(os.tmpdir(), 'spike-s5');
    const { mkdirSync, writeFileSync } = await import('node:fs');
    mkdirSync(dir, { recursive: true });

    // The golden text itself (with legend), for the record of what Mermaid draws in the shipped `completo`.
    if (!ONLY || ONLY === 'visual') {
      const ms = await mermaidRender(textoGolden);
      (comparacao as any).mermaid_golden_com_legenda = { render_ms_cpu_1x: r1(ms), ...(await medirCena('mermaid')) };
    }

    for (const c of CONJUNTOS) {
      const texto = gerarDiagramaExpandido(grafo, conjDe(c), false).texto;
      const msM = await mermaidRender(texto);
      const m = await medirCena('mermaid');
      const fotoM = await foto();
      writeFileSync(join(dir, `${c.id}.mermaid.png`), fotoM);
      const msP = await proprioRender(c);
      const p = await medirCena('proprio');
      const fotoP = await foto();
      writeFileSync(join(dir, `${c.id}.proprio.png`), fotoP);
      const pix = await compararFotos(fotoM, fotoP);
      const fotoM2 = await fotoNoMermaid(c, texto);
      await proprioRender(c);
      const pixEsticado = await compararFotos(fotoM2, await foto('none'));
      const rel = (a: number, b: number) => (a ? round((b / a) * 100, 1) : null);
      porConjunto[c.id] = {
        mermaid_sem_legenda: { render_ms_cpu_1x: r1(msM), ...m },
        proprio: { render_ms_cpu_1x: r1(msP), ...p },
        diferenca: {
          nos_proprio_sobre_mermaid_pct: rel(m.nos, p.nos),
          arestas_proprio_sobre_mermaid_pct: rel(m.arestas, p.arestas),
          clusters_proprio_sobre_mermaid_pct: rel(m.clusters, p.clusters),
          rotulos_de_aresta_proprio_sobre_mermaid_pct: rel(m.rotulos_de_aresta, p.rotulos_de_aresta),
          area_natural_proprio_sobre_mermaid_pct: rel(m.tamanho_natural.largura * m.tamanho_natural.altura, p.tamanho_natural.largura * p.tamanho_natural.altura),
          svg_chars_proprio_sobre_mermaid_pct: rel(m.svg_chars, p.svg_chars),
          elementos_no_svg_proprio_sobre_mermaid_pct: rel(m.elementos_no_svg, p.elementos_no_svg),
        },
        pixels_grosseiro: pix,
        pixels_grosseiro_esticado_sem_manter_proporcao: pixEsticado,
      };
    }
  } finally {
    await fecharCtx();
  }
  relatorio.leitura = {
    comparacao_com_mermaid:
      'compare `desempenho.por_conjunto.*.worker.total_ms.p95` com `mermaid_s1_p95_ms`. O Worker não sofre o CPU 4x (`calibragem_do_cpu_4x`), então `total_estimado_se_o_worker_fosse_4x_ms` e o controle na thread principal dão o intervalo honesto para um aparelho 4x mais lento.',
    resposta_do_mouse:
      'o layout sai da thread principal e some o bloqueio de segundos do controle, mas o `innerHTML` e a geração do SVG continuam nela: o pior momento fica em ordem de 100 a 200 ms, perto do alvo de 100 ms e não abaixo dele. Reduzir exige inserir o SVG em fatias ou usar OffscreenCanvas/virtualização.',
    lacunas_visuais: [
      'tamanho do texto estimado por contagem de caracteres (o Worker não tem DOM): há nós em que o texto não cabe na forma (`texto_excede_a_forma`), sobretudo gateways',
      'dagre não reserva espaço para título nem margem de cluster: o protótipo desenha o retângulo da raia maior que a caixa do dagre, e raias vizinhas chegam a se sobrepor (`cluster_sobre_cluster_nao_aninhado`); o Mermaid corrige isso por dentro',
      'a posição e a proporção do desenho divergem do Mermaid (a ordem dentro da raia e as larguras mudam), por isso a comparação de pixels é só grosseira',
      'sem legenda, sem interatividade, sem foco por teclado e sem medição de texto em fonte real; arestas sem desvio de cluster',
      'o `label-overlap` (rótulo de cluster coberto por nó) ficou verde, mas só porque o título vive numa faixa acima da caixa do dagre',
    ],
  };
  relatorio.fidelidade_visual = {
    golden: comparacao,
    imagens: `capturas em ${join(os.tmpdir(), 'spike-s5')} (não versionadas): <conjunto>.mermaid.png e <conjunto>.proprio.png, ambas ajustadas a 1600x1200`,
    metodo:
      'o Mermaid recebe o texto de gerarDiagramaExpandido sem legenda (o protótipo não desenha legenda); contagens por g.node, g.cluster, path.flowchart-link (Mermaid) e path.edge (protótipo); label-overlap igual ao oráculo de tests/browser/label-overlap.spec.ts; comparação de pixels grosseira (grade 160x120 de luminância e presença de tinta) porque os dois layouts divergem em posição e escala, então ela mede densidade e distribuição, não identidade',
    por_conjunto: porConjunto,
  };
  fechar(browser.version());
  expect(porConjunto).toBeTruthy();
});
